      '.wb-hero{background:linear-gradient(135deg,#1e1145 0%,#2d1b69 52%,#172554 100%);border:1px solid rgba(167,139,250,0.42);box-shadow:0 10px 26px rgba(30,17,69,0.22);color:#f8fafc;}',
