      '@keyframes wb-glint-twinkle{0%,100%{opacity:0.35;transform:scale(0.90);}50%{opacity:0.96;transform:scale(1.14);}}',
      '@keyframes wb-radar-breathe{0%,100%{opacity:0.18;}50%{opacity:0.46;}}',
